def get_valid_operation():
    """Get a valid operation from the user."""
    while True:
        operation = input("Choose an operation (+, -, *, /): ").upper()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("Invalid input. Please try again.")

def get_numbers():
    """Get two numbers as input and validate them."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers only.")

def perform_operation(num1, num2, operation):
    """Perform the given operation on the two numbers."""
    if operation == '+':
        result = num1 + num2
    elif operation == '-':
        result = num1 - num2
    elif operation == '*':
        result = num1 * num2
    elif operation == '/':
        if num2 == 0:
            print("Error: Division by zero is not allowed.")
            return None
        result = num1 / num2
    else:
        print("Invalid operation. Please try again.")
        return None
    return result

def main():
    print("Number Calculator")
    while True:
        operation = get_valid_operation()
        if operation == 'Q':
            print("Exiting the program...")
            break
        num1, num2 = get_numbers()
        result = perform_operation(num1, num2, operation)
        if result is not None:
            print(f"{num1} {operation} {num2} = {result:.2f}")

if __name__ == "__main__":
    main()
```

This program defines several functions to handle user input, validate numbers, and perform operations. The `main` function calls these functions in a loop, allowing the user to continue using the calculator until they choose to quit (`'Q'`). The program also checks for division by zero and prints an error message if it occurs.
